---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';

export interface Props extends HTMLAttributes<'div'> {}

const { class: className, ...props } = Astro.props;
---

<div class={cn('relative inline-block', className)} data-tooltip {...props}>
  <slot />
</div>

<script>
  import { generateId } from '@/utils/focus-trap';
  import { positionFloating, type FloatingSide } from '@/utils/position';

  function initTooltips() {
    document.querySelectorAll('[data-tooltip]').forEach((tooltip) => {
      if (tooltip.hasAttribute('data-initialized')) return;
      tooltip.setAttribute('data-initialized', 'true');

      const trigger = tooltip.querySelector('[data-tooltip-trigger]') as HTMLElement;
      const content = tooltip.querySelector('[data-tooltip-content]') as HTMLElement;

      if (!trigger || !content) return;

      // Generate ID for content if not present
      if (!content.id) {
        content.id = generateId('tooltip');
      }

      // Link trigger to content via aria-describedby
      trigger.setAttribute('aria-describedby', content.id);

      let cleanupPosition: (() => void) | null = null;

      const showTooltip = () => {
        content.hidden = false;
        cleanupPosition = positionFloating(trigger, content, {
          side: (content.dataset.side as FloatingSide) || 'top',
        });
      };

      const hideTooltip = () => {
        content.hidden = true;
        cleanupPosition?.();
        cleanupPosition = null;
      };

      trigger.addEventListener('mouseenter', showTooltip);
      trigger.addEventListener('mouseleave', hideTooltip);
      trigger.addEventListener('focus', showTooltip);
      trigger.addEventListener('blur', hideTooltip);

      // Hide on Escape
      trigger.addEventListener('keydown', (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
          hideTooltip();
        }
      });
    });
  }

  initTooltips();
  document.addEventListener('astro:page-load', initTooltips);
</script>

---
import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";

export interface Props extends HTMLAttributes<"div"> {
  side?: "top" | "right" | "bottom" | "left";
  id?: string;
}

const { side = "top", class: className, id, ...props } = Astro.props;

const classes = cn(
  "z-50 overflow-hidden rounded-md border bg-popover px-3 py-1.5 text-sm text-popover-foreground shadow-md whitespace-nowrap",
  className,
);
---

<div
  class={classes}
  data-tooltip-content
  data-side={side}
  role="tooltip"
  id={id}
  hidden
  {...props}
>
  <slot />
</div>

